// Tool objects for tools/list: descriptions + inputSchemas are verbatim
// from the python live capture (tools/list id=2); `do` is present (P2
// seam). Post-capture sentences appended to the descriptions document
// element fp, stale_ref, and the UIPI errors; no captured text was edited.
// P2a: `_meta.fastmcp.tags` noise removed and every tool carries a real
// `outputSchema` matching its `structuredContent` (the python capture's
// `x-fastmcp-wrap-result` string wrapper is gone).
pub const TOOL_SCREENSHOT: &str = r#"{"description": "Capture the whole virtual desktop (display=-1), one monitor, a window (window=<selector> or target={...}) or a region, without activating the window: no cursor movement, no focus change.\nReturns {ok, image{w,h,format,quality}, source{x,y,w,h}, scale, monitors, cursor{x,y}, formula, capture{...}, elements?}. source is SCREEN pixels; the returned image maps back with screen_x = source.x + round((img_x + 0.5) * source.w / image.w), the same for y - formula carries that verbatim, and scale is the long-edge clamp that produced the image.\nfmt defaults to jpeg (png when out is set); quality applies to jpeg only, 1..100. A minimized window returns window_minimized; a refused frame returns capture_unavailable. capture.moved_during_capture flags a window that moved while it was captured, so the frame may mix two positions. elements:true adds the structured element block, whose elements_window names the hwnd it enumerated. For an illegible control, re-request the same window with a tight region and max_px:null (full-resolution crop).\nforegroundUnchanged/cursorUnchanged report the measured before/after invariant.", "inputSchema": {"type": "object", "additionalProperties": false, "properties": {"target": {"anyOf": [{"type": "object", "additionalProperties": false, "properties": {"hwnd": {"type": "integer"}, "pid": {"type": "integer"}, "exe": {"type": "string"}, "appId": {"type": "string"}, "titleContains": {"type": "string"}, "className": {"type": "string"}}}, {"type": "string"}, {"type": "null"}], "default": null}, "display": {"type": "integer", "default": -1}, "region": {"anyOf": [{"type": "array", "items": {"type": "integer"}, "minItems": 4, "maxItems": 4}, {"type": "null"}], "default": null}, "window": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null}, "max_px": {"anyOf": [{"type": "integer", "minimum": 1, "maximum": 8192}, {"type": "null"}], "default": 1280}, "fmt": {"type": "string", "enum": ["png", "jpeg", "jpg"], "default": "jpeg"}, "quality": {"type": "integer", "minimum": 1, "maximum": 100, "default": 80}, "grid": {"type": "boolean", "default": false}, "allow_crop_fallback": {"type": "boolean", "default": false}, "elements": {"type": "boolean", "default": false}, "out": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null}}}, "name": "screenshot", "outputSchema": {"type": "object", "properties": {"image": {"type": "object"}, "source": {"type": "object"}, "scale": {"type": "number"}, "monitors": {"type": "object"}, "cursor": {"type": "object"}, "window": {"type": "object"}, "capture": {"type": "object"}, "formula": {"type": "string"}, "foregroundUnchanged": {"type": "boolean"}, "cursorUnchanged": {"type": "boolean"}}, "required": ["image", "source", "scale", "monitors", "cursor", "capture", "formula"], "additionalProperties": true}, "title": "Screenshot", "annotations": {"title": "Screenshot", "readOnlyHint": true, "destructiveHint": false, "idempotentHint": true, "openWorldHint": false}}"#;
pub const TOOL_DIFF: &str = r#"{"description": "Pixel diff for \"only the intended pixels changed\": compare two captures and report exactly which pixels moved. Each of base/next is either {path:\"<png>\"} (an absolute .png path, decoded as-is) or a capture target ({target|window, display, region} with the same selector grammar as screenshot; captured side-effect-free at native pixels, never activated or raised). Both sides must decode/capture to the SAME pixel dimensions: a mismatch is a typed size_mismatch naming both sizes, never a silent scale. threshold (0-255 per channel, default 0) is the only tolerance; max_px (default 1280) is a long-edge clamp for the returned diff image, aspect-preserving, never upscaling; out writes the diff PNG to an absolute path (parents created); bbox (default true) toggles the union box. Returns {changed,total,ratio,bbox:[x,y,w,h]|null,identical,base:{w,h},next:{w,h},threshold,diff_out?}; when anything changed a second content block carries the diff image (changed pixels solid red over a dimmed greyscale copy of base). Read-only: no activation, no input. Errors never raise.", "inputSchema": {"type": "object", "additionalProperties": false, "properties": {"base": {"anyOf": [{"type": "object"}, {"type": "string"}]}, "next": {"anyOf": [{"type": "object"}, {"type": "string"}]}, "threshold": {"type": "integer", "minimum": 0, "maximum": 255, "default": 0}, "max_px": {"anyOf": [{"type": "integer", "minimum": 1, "maximum": 8192}, {"type": "null"}], "default": 1280}, "out": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null}, "bbox": {"type": "boolean", "default": true}}, "required": ["base", "next"]}, "name": "diff", "outputSchema": {"type": "object", "properties": {"ok": {"type": "boolean"}, "changed": {"type": "integer"}, "total": {"type": "integer"}, "ratio": {"type": "number"}, "bbox": {"anyOf": [{"type": "array"}, {"type": "null"}]}, "identical": {"type": "boolean"}, "base": {"type": "object"}, "next": {"type": "object"}, "threshold": {"type": "integer"}, "diff_out": {"anyOf": [{"type": "object"}, {"type": "null"}]}}, "required": ["ok", "changed", "total", "ratio", "identical", "base", "next"], "additionalProperties": true}, "title": "Diff", "annotations": {"title": "Diff", "readOnlyHint": true, "destructiveHint": false, "idempotentHint": true, "openWorldHint": false}}"#;
pub const TOOL_LIST_WINDOWS: &str = r#"{"description": "List visible top-level windows as JSON:\n[{hwnd,pid,exe,title,class,rect:[l,t,r,b],dwm_rect,client_rect,\nminimized,maximized,foreground,cloaked,visible,dpi}].\nrect=GetWindowRect (compat, includes the invisible border);\ndwm_rect=DWMWA_EXTENDED_FRAME_BOUNDS (mapping truth, else rect with\ndwm_fallback:true); client_rect in screen space. Read-only: no focus\nchange, no window is touched.\nelevated names the target's integrity: true when its process runs\nelevated (input from this unelevated server is UIPI-blocked: refused\nbefore injecting with uipi_blocked, flagged blocked_by_uipi:true),\nfalse when not elevated, null when unreadable (never named elevated).\ninclude_app_ids (default false) adds appId per window from the window's\nAppUserModelID property store (a string, or null when the store/property is\nunavailable). It is opt-in because that read is a per-window COM call.", "inputSchema": {"properties": {"include_app_ids": {"type": "boolean", "default": false}}, "type": "object", "additionalProperties": false}, "name": "list_windows", "outputSchema": {"type": "object", "properties": {"windows": {"type": "array", "items": {"type": "object"}}}, "required": ["windows"], "additionalProperties": true}, "title": "List Windows", "annotations": {"title": "List Windows", "readOnlyHint": true, "destructiveHint": false, "idempotentHint": true, "openWorldHint": false}}"#;
pub const TOOL_WINDOW: &str = r#"{"description": "Move, resize, minimize, restore, close or raise a window by selector, hwnd or target; every verb is no-steal (SWP_NOACTIVATE / SW_SHOWMINNOACTIVE) and never touches the owner's cursor, keyboard or clipboard.\naction=focus and action=maximize are refused with no_foreground_policy: focusing IS taking the foreground and maximize covers a monitor. move needs x,y; resize needs width,height; close posts WM_CLOSE.\nReturns {ok, action, hwnd} plus the verb's fields. An ambiguous or vanished target is typed (ambiguous_target / target_gone) and never falls back to the foreground window. Read-only listing, capture and element walks are list_windows, screenshot and elements.", "inputSchema": {"type": "object", "additionalProperties": false, "properties": {"action": {"type": "string", "enum": ["focus", "move", "resize", "minimize", "maximize", "restore", "close", "topmost"]}, "title": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null}, "hwnd": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null}, "x": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null}, "y": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null}, "width": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null}, "height": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null}, "target": {"anyOf": [{"type": "object", "additionalProperties": false, "properties": {"hwnd": {"type": "integer"}, "pid": {"type": "integer"}, "exe": {"type": "string"}, "appId": {"type": "string"}, "titleContains": {"type": "string"}, "className": {"type": "string"}}}, {"type": "string"}, {"type": "null"}], "default": null}, "allow_foreground": {"type": "boolean", "default": false}}, "required": ["action"], "allOf": [{"if": {"properties": {"action": {"const": "move"}}}, "then": {"required": ["x", "y"]}}, {"if": {"properties": {"action": {"const": "resize"}}}, "then": {"required": ["width", "height"]}}]}, "name": "window", "outputSchema": {"type": "object", "properties": {"ok": {"type": "boolean"}, "action": {"type": "string"}, "hwnd": {"type": "integer"}, "x": {"type": "integer"}, "y": {"type": "integer"}, "width": {"type": "integer"}, "height": {"type": "integer"}, "error": {"type": "string"}, "candidates": {"type": "array"}, "code": {"type": "string"}, "foregroundUnchanged": {"type": "boolean"}, "cursorUnchanged": {"type": "boolean"}, "target_locked": {"type": "integer"}}, "required": ["ok"], "additionalProperties": true}, "title": "Window", "annotations": {"title": "Window", "readOnlyHint": false, "destructiveHint": true, "idempotentHint": false, "openWorldHint": false}}"#;
pub const TOOL_DO: &str = r#"{"description": "BURST tool: one call runs an ordered actions[] batch against one window.\ntarget={hwnd?,pid?,exe?,appId?,titleContains?,className?} (or a selector string) locks ONE top-level window for the whole call and is revalidated before every action; the legacy background selector is an alternative lock and target wins when both are given. Without a target every acting verb is refused before anything is sent (target_required for keys and patterns, no_cursor_policy for pointer acts), and nothing ever falls back to the foreground window.\nDelivery: click/down/up/drag/scroll/type/key/hotkey post window messages to the locked target; click, scroll and invoke with an element prefer the control UIA pattern (Invoke, SelectionItem, Toggle, ExpandCollapse, ScrollPattern), and click falls back to a posted button message at the element centre whose readable state is read before and after; wait, wait_for and clipboard_get deliver nothing. Refused under the policy, with no flag that unlocks them: move is refused with no_cursor_policy (a cursor move is not a window message); focus_window is refused with no_foreground_policy; set_value is refused with background_unavailable (UIA SetValue may focus the control); clipboard_set is refused with no_clipboard_policy (the clipboard is global); and type with an element is refused with background_unavailable.\nCoordinates: x/y under a target are CLIENT-area physical pixels; without a target they are virtual-desktop SCREEN pixels converted with ScreenToClient. Posted coordinates are signed 16-bit: anything outside -32768..32767 is refused with bad_coordinates before a message is posted. move takes x/y or dx/dy, never both.\nEffects: every result carries delivered (uia|posted|none), via and effect. ok is true when the action was delivered and not disproven; a posted click whose readable control state did not change reports ok:false with background_unavailable and effect unchanged; a raw x/y click reports effect unverified.\nStale refs: every element mutation (invoke, set_value, click and type with an element) requires expect_fp, the fp from an elements entry. Without it the call refuses expect_fp_required and the error carries the fresh fp; a mismatch refuses resolution:stale with a stale_ref error naming expected vs found fps. Retry with the returned fp. fp is identity, never state: rect, text and control state do not participate, so a matching fp means the same control, not the same condition; read effect for what the control then did. An ambiguous selector returns candidates {name,role,auto_id,rect,ref,fp} and acts on nothing; an explicit index picks the nth match.\nKeyboard: type posts WM_CHAR per unit; key and hotkey post WM_KEYDOWN/WM_SYSKEYDOWN and hold Shift when the layout requires it. chunk_chars/chunk_ms are accepted for compatibility and perform no pacing. scroll axis v|h selects the wheel; drag is down/move/up at exact points; hover:true is the only way to post a WM_MOUSEMOVE.\nBudget: at most 256 actions and 300 ms of total elapsed time per call; exceeding either is a typed burst_budget_exceeded result naming the limit and the actual value, and the remaining actions do not run. An element wait reports satisfied_by {selector, fp, path} naming the control that satisfied it (null when nothing did) and fp_matched when expect_fp was supplied; a mismatch is a report, never an error. Top-level ok is true only when EVERY action succeeded; a wait_for timeout is never an error. settle_ms is one trailing pause after the last action. focus_guard:true restores the entry foreground window when the call changed it, and focus_before/focus_after are always reported.\ndry_run=true validates exactly like the live call (every policy refusal included) but posts nothing, and invoke under dry_run still reports found|not-found|ambiguous. desktop:\"hidden\" launches the program named by background on a private desktop (background_args are its argv) and returns the burst JSON plus hidden_desktop{...}; the owner's cursor, foreground and focus are never touched.", "inputSchema": {"type": "object", "additionalProperties": false, "properties": {"actions": {"type": "array", "minItems": 1, "maxItems": 256, "items": {"oneOf": [{"type": "object", "properties": {"type": {"const": "move"}, "x": {"type": "integer"}, "y": {"type": "integer"}, "dx": {"type": "integer"}, "dy": {"type": "integer"}, "relative": {"type": "boolean"}}, "required": ["type"], "anyOf": [{"required": ["x", "y"]}, {"required": ["dx", "dy"]}]}, {"type": "object", "properties": {"type": {"const": "click"}, "x": {"type": "integer"}, "y": {"type": "integer"}, "button": {"type": "string"}, "count": {"type": "integer"}, "hover": {"type": "boolean", "default": false}, "element": {"type": "string"}, "index": {"type": "integer"}, "expect_fp": {"type": "string", "description": "Required for element mutations as of 8.0.0"}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "down"}, "button": {"type": "string"}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "up"}, "button": {"type": "string"}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "drag"}, "from": {"type": "array", "items": {"type": "integer"}, "minItems": 2, "maxItems": 2}, "to": {"type": "array", "items": {"type": "integer"}, "minItems": 2, "maxItems": 2}, "button": {"type": "string"}}, "required": ["type", "from", "to"]}, {"type": "object", "properties": {"type": {"const": "scroll"}, "x": {"type": "integer"}, "y": {"type": "integer"}, "amount": {"type": "integer"}, "axis": {"type": "string", "enum": ["v", "h"], "default": "v"}, "element": {"type": "string"}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "type"}, "text": {"type": "string"}, "chunk_chars": {"type": "integer"}, "chunk_ms": {"type": "integer"}, "element": {"type": "string"}, "index": {"type": "integer"}, "expect_fp": {"type": "string", "description": "Required for element mutations as of 8.0.0"}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "key"}, "name": {"type": "string"}, "hold_ms": {"type": "integer", "minimum": 0, "maximum": 60000}, "repeat": {"type": "integer", "minimum": 1, "maximum": 100}, "gap_ms": {"type": "integer", "minimum": 0, "maximum": 60000}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "hotkey"}, "keys": {"anyOf": [{"type": "array", "items": {"type": "string"}}, {"type": "string"}]}}, "required": ["type", "keys"]}, {"type": "object", "properties": {"type": {"const": "wait"}, "ms": {"type": "integer"}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "wait_for"}, "kind": {"type": "string", "enum": ["window_appear", "window_disappear", "pixel", "stable", "element"]}, "selector": {"type": "string"}, "x": {"type": "integer"}, "y": {"type": "integer"}, "color": {"type": "array", "items": {"type": "integer"}, "minItems": 3, "maxItems": 3}, "tolerance": {"type": "integer"}, "region": {"type": "array", "items": {"type": "integer"}, "minItems": 4, "maxItems": 4}, "timeout_ms": {"type": "integer"}, "poll_ms": {"type": "integer"}, "window": {"type": "string"}, "element": {"type": "string"}, "expect_fp": {"type": "string", "description": "Reported as fp_matched; never turns the wait into an error"}, "state": {"type": "string", "enum": ["appear", "disappear", "enabled", "disabled"], "default": "appear"}}, "required": ["type", "kind"]}, {"type": "object", "properties": {"type": {"const": "focus_window"}, "title": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null}, "hwnd": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "invoke"}, "element": {"type": "string"}, "index": {"type": "integer"}, "expect_fp": {"type": "string", "description": "Required for element mutations as of 8.0.0"}, "state": {"type": "string", "enum": ["expand", "collapse"]}}, "required": ["type", "element"]}, {"type": "object", "properties": {"type": {"const": "set_value"}, "element": {"type": "string"}, "text": {"type": "string"}, "expect_fp": {"type": "string", "description": "Required for element mutations as of 8.0.0"}}, "required": ["type", "element", "text"]}, {"type": "object", "properties": {"type": {"const": "clipboard_set"}, "text": {"type": "string"}}, "required": ["type"]}, {"type": "object", "properties": {"type": {"const": "clipboard_get"}}, "required": ["type"]}]}}, "background": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null}, "background_args": {"anyOf": [{"type": "array", "items": {"type": "string"}}, {"type": "null"}], "default": null}, "focus_guard": {"type": "boolean", "default": false}, "settle_ms": {"type": "integer", "default": 0}, "dry_run": {"type": "boolean", "default": false}, "desktop": {"anyOf": [{"type": "string", "enum": ["hidden"]}, {"type": "null"}], "default": null}, "target": {"anyOf": [{"type": "object", "additionalProperties": false, "properties": {"hwnd": {"type": "integer"}, "pid": {"type": "integer"}, "exe": {"type": "string"}, "appId": {"type": "string"}, "titleContains": {"type": "string"}, "className": {"type": "string"}}}, {"type": "string"}, {"type": "null"}], "default": null}, "allow_foreground": {"type": "boolean", "default": false}, "allow_cursor": {"type": "boolean", "default": false}, "allow_clipboard": {"type": "boolean", "default": false, "description": "Retained for schema compatibility and buys nothing: it would permit overwriting the owner's global clipboard, and clipboard_set is refused with no_clipboard_policy before OpenClipboard whatever this is set to. Reads (clipboard_get) never need it, and a refused call touches no clipboard."}}, "required": ["actions"]}, "name": "do", "outputSchema": {"type": "object", "properties": {"ok": {"type": "boolean"}, "failed": {"type": "integer"}, "results": {"type": "array"}, "total_ms": {"type": "number"}, "sendinput_calls": {"type": "integer"}, "sendinput_ms": {"type": "number"}, "events": {"type": "integer"}, "focus_before": {"type": "integer"}, "focus_after": {"type": "integer"}, "foregroundUnchanged": {"type": "boolean"}, "cursorUnchanged": {"type": "boolean"}, "target_locked": {"type": "integer"}, "target_pid": {"type": "integer"}, "target_exe": {"type": "string"}}, "required": ["results", "total_ms", "sendinput_calls", "sendinput_ms", "events", "focus_before", "focus_after"], "additionalProperties": true}, "title": "Do", "annotations": {"title": "Do", "readOnlyHint": false, "destructiveHint": true, "idempotentHint": false, "openWorldHint": false}}"#;
pub const TOOL_CURSOR: &str = r#"{"description": "Current cursor position + monitor rects as JSON:\n{x, y, screens:[[l,t,r,b],...]}.", "inputSchema": {"properties": {}, "type": "object", "additionalProperties": false}, "name": "cursor", "outputSchema": {"type": "object", "properties": {"x": {"type": "integer"}, "y": {"type": "integer"}, "screens": {"type": "array"}}, "required": ["x", "y", "screens"], "additionalProperties": true}, "title": "Cursor", "annotations": {"title": "Cursor", "readOnlyHint": true, "destructiveHint": false, "idempotentHint": true, "openWorldHint": false}}"#;
pub const TOOL_ELEMENTS: &str = r#"{"description": "List structured UI elements for a window as JSON, zero-pixel (no screenshot, no focus change, no input).\nTarget by selector (title text or hwnd; the same TargetLock as target:). detail=true keeps the raw win and hwnd fields on each entry and adds text (TextPattern document text, capped at 4000 chars) plus text_truncated; the default false returns the compact {ref,role,name,auto_id,rect,offscreen,invokable,path,fp}.\nEach entry carries fp, a stable identity fingerprint (FNV-1a over role/name/auto_id/invokable, 16 hex chars); pass it as expect_fp to invoke, set_value, click and type on an element: a call without one is refused with the fresh fp, and a mismatched one refuses stale_ref instead of acting on the wrong control. fp is identity, never state: rect, text and control state (checked, selected, expanded, range) do not participate, so an fp match means the same control, not the same condition; a state-sensitive action needs a readback (effect), never a fingerprint. offscreen:true marks a control with no area: the rect is kept for shape stability but click refuses it with offscreen_element.\nReturns {backend,truncated,rect_space,elements,uia_available,uia_error,fallback,empty[,empty_reason],depth_capped,depth_limit}; rect_space is screen. max_depth (1..32, default 8) bounds the UIA walk; offset pages past the 200-entry cap and next_offset carries the next page or null. When UIA is unavailable the Win32 child enumeration serves the entries.", "inputSchema": {"type": "object", "additionalProperties": false, "properties": {"title": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null}, "hwnd": {"anyOf": [{"type": "integer"}, {"type": "null"}], "default": null}, "detail": {"type": "boolean", "default": false}, "max_depth": {"type": "integer", "minimum": 1, "maximum": 32, "default": 8}, "offset": {"type": "integer", "minimum": 0, "default": 0}, "target": {"anyOf": [{"type": "object", "additionalProperties": false, "properties": {"hwnd": {"type": "integer"}, "pid": {"type": "integer"}, "exe": {"type": "string"}, "appId": {"type": "string"}, "titleContains": {"type": "string"}, "className": {"type": "string"}}}, {"type": "string"}, {"type": "null"}], "default": null}}, "anyOf": [{"required": ["title"]}, {"required": ["hwnd"]}, {"required": ["target"]}]}, "name": "elements", "outputSchema": {"type": "object", "properties": {"backend": {"type": "string"}, "truncated": {"type": "boolean"}, "rect_space": {"type": "string"}, "elements": {"type": "array"}, "uia_available": {"type": "boolean"}, "uia_error": {}, "fallback": {}, "empty": {"type": "boolean"}, "empty_reason": {"type": "string"}, "depth_capped": {"type": "boolean"}, "depth_limit": {"type": "integer"}, "foregroundUnchanged": {"type": "boolean"}, "cursorUnchanged": {"type": "boolean"}}, "required": ["backend", "truncated", "rect_space", "elements", "uia_available", "empty", "depth_capped", "depth_limit"], "additionalProperties": true}, "title": "Elements", "annotations": {"title": "Elements", "readOnlyHint": true, "destructiveHint": false, "idempotentHint": true, "openWorldHint": false}}"#;
